(function(root){const M={initial:()=>({stopped:false,blocked:false,listed:true,request:null,records:[]}),canPublish:(s,qualified,deleted)=>!s.stopped&&!s.blocked&&qualified&&!deleted,act(state,action,reason){if(!reason?.trim())throw Error('请填写说明');const s=structuredClone(state);if(action==='warn'){}else if(action==='stop'){if(s.stopped)throw Error('店铺已经停业');s.stopped=true;s.request=null;}else if(action==='emergency'){if(s.blocked)throw Error('商品已被紧急下架');s.blocked=true;s.listed=false;s.request=null;}else if(action==='request'){if(!s.stopped&&!s.blocked)throw Error('当前没有待解除的限制');if(s.request?.status==='待审核')throw Error('申请正在审核中');s.request={status:'待审核',reason:reason.trim()};}else if(action==='approve'||action==='reject'){if(s.request?.status!=='待审核')throw Error('没有待审核申请');s.request.status=action==='approve'?'已通过':'已驳回';s.request.result=reason.trim();if(action==='approve'){s.stopped=false;s.blocked=false;}}else throw Error('未知操作');s.records.push({action,reason:reason.trim(),time:new Date().toLocaleString('zh-CN')});return s;}};if(typeof module!=='undefined')module.exports=M;else root.AdminModel=M;})(globalThis);
